export function decodeDurableRecordBytesV1(type: EntityTypeV1, bytes: Uint8Array): T.DurableEntityV1 | T.RootHeaderV1 { return decodeEntityV1(type, parseStrictJsonV1(bytes)); }

/**
 * checkpoint 解码时每个集合的条数上限。写路径（store commit）用同一组常量预检，
 * 超限的事务以 storage-capacity 拒绝，不能写出一个读不回来的 checkpoint。
 */
export const ROOT_COLLECTION_BOUNDS = { agent_ids: 4096, mailbox: 1024, inbox: 4096, outbox: 4096, owner_events: 4096, operation_receipts: 4096, wake_receipts: 4096, cleanup: 4096, tombstones: 4096 } as const;
export const AGENT_COLLECTION_BOUNDS = { tasks: 256, mailbox: 1024, completions: 256, inbox: 4096, outbox: 4096, owner_events: 4096, operation_receipts: 4096, wake_receipts: 4096 } as const;
function decodeRecordArray<TValue>(value: unknown, label: string, decoder: (item: unknown) => TValue, max: number): TValue[] { if (!Array.isArray(value) || value.length > max) throw new Error(`${label} must be bounded array`); return value.map(decoder); }
const ROOT_HEADER_KEYS = ["version", "main_key", "host_revision", "next_admission_order", "next_mailbox_sequence", "next_owner_event_sequence", "last_owner_event_acked_sequence", "agent_ids"] as const;
function rootHeaderFields(i: ObjectValue): T.RootHeaderV1 { if (!isMainKey(i.main_key)) throw new Error("root main key is invalid"); return { version: literal(i.version, 1, "root version"), main_key: i.main_key, host_revision: integer(i.host_revision, "host revision"), next_admission_order: integer(i.next_admission_order, "next admission", 1), next_mailbox_sequence: integer(i.next_mailbox_sequence, "next mailbox", 1), next_owner_event_sequence: integer(i.next_owner_event_sequence, "next owner event", 1), last_owner_event_acked_sequence: integer(i.last_owner_event_acked_sequence, "last owner ack"), agent_ids: ids(i.agent_ids, "agt", "root agents", 0, ROOT_COLLECTION_BOUNDS.agent_ids) as never }; }
export function decodeRootHeaderV1(value: unknown): T.RootHeaderV1 { return rootHeaderFields(object(value, ROOT_HEADER_KEYS)); }
/** 取 Root 头写进 journal 的 Root put；调用方再覆盖要改的头字段（host_revision 等）。 */
export function rootHeaderV1(root: T.RootHeaderV1): T.RootHeaderV1 { return { version: root.version, main_key: root.main_key, host_revision: root.host_revision, next_admission_order: root.next_admission_order, next_mailbox_sequence: root.next_mailbox_sequence, next_owner_event_sequence: root.next_owner_event_sequence, last_owner_event_acked_sequence: root.last_owner_event_acked_sequence, agent_ids: [...root.agent_ids] }; }
export function decodeRootCheckpointV1(value: unknown): T.RootCheckpointV1 { const i = object(value, [...ROOT_HEADER_KEYS, "mailbox", "inbox", "outbox", "owner_events", "operation_receipts", "wake_receipts", "cleanup", "tombstones"], ["barrier"]); return { ...rootHeaderFields(i), mailbox: decodeRecordArray(i.mailbox, "root mailbox", decodeMailboxRecordV1, ROOT_COLLECTION_BOUNDS.mailbox), inbox: decodeRecordArray(i.inbox, "root inbox", decodeInboxRecordV1, ROOT_COLLECTION_BOUNDS.inbox), outbox: decodeRecordArray(i.outbox, "root outbox", decodeOutboxRecordV1, ROOT_COLLECTION_BOUNDS.outbox), owner_events: decodeRecordArray(i.owner_events, "root events", decodeOwnerEventRecordV1, ROOT_COLLECTION_BOUNDS.owner_events), ...(i.barrier !== undefined ? { barrier: decodeBarrierRecordV1(i.barrier) } : {}), operation_receipts: decodeRecordArray(i.operation_receipts, "root operation receipts", decodeOperationReceiptV1, ROOT_COLLECTION_BOUNDS.operation_receipts), wake_receipts: decodeRecordArray(i.wake_receipts, "root wake receipts", decodeWakeSettlementReceiptV1, ROOT_COLLECTION_BOUNDS.wake_receipts), cleanup: decodeRecordArray(i.cleanup, "root cleanup", decodeCleanupRecordV1, ROOT_COLLECTION_BOUNDS.cleanup), tombstones: decodeRecordArray(i.tombstones, "root tombstones", decodeSubtreeTombstoneV1, ROOT_COLLECTION_BOUNDS.tombstones) }; }
export function decodeAgentCheckpointV1(value: unknown): T.AgentCheckpointV1 { const i = object(value, ["version", "host_revision", "agent", "tasks", "mailbox", "completions", "inbox", "outbox", "owner_events", "operation_receipts", "wake_receipts"], ["barrier"]); return { version: literal(i.version, 1, "agent checkpoint version"), host_revision: integer(i.host_revision, "agent checkpoint revision"), agent: decodeAgentRecordV1(i.agent), tasks: decodeRecordArray(i.tasks, "tasks", decodeTaskRecordV1, AGENT_COLLECTION_BOUNDS.tasks), mailbox: decodeRecordArray(i.mailbox, "agent mailbox", decodeMailboxRecordV1, AGENT_COLLECTION_BOUNDS.mailbox), ...(i.barrier !== undefined ? { barrier: decodeBarrierRecordV1(i.barrier) } : {}), completions: decodeRecordArray(i.completions, "completions", decodeCompletionRecordV1, AGENT_COLLECTION_BOUNDS.completions), inbox: decodeRecordArray(i.inbox, "inbox", decodeInboxRecordV1, AGENT_COLLECTION_BOUNDS.inbox), outbox: decodeRecordArray(i.outbox, "outbox", decodeOutboxRecordV1, AGENT_COLLECTION_BOUNDS.outbox), owner_events: decodeRecordArray(i.owner_events, "owner events", decodeOwnerEventRecordV1, AGENT_COLLECTION_BOUNDS.owner_events), operation_receipts: decodeRecordArray(i.operation_receipts, "operation receipts", decodeOperationReceiptV1, AGENT_COLLECTION_BOUNDS.operation_receipts), wake_receipts: decodeRecordArray(i.wake_receipts, "wake receipts", decodeWakeSettlementReceiptV1, AGENT_COLLECTION_BOUNDS.wake_receipts) }; }
export function checkpointDigestV1(value: T.RootCheckpointV1 | T.AgentCheckpointV1): string { return sha256CanonicalV1(value); }
